
console.log('Admin layout module loaded');
document.addEventListener('DOMContentLoaded', function() {
    
    const adminButtons = document.querySelectorAll('.btn-admin-primary, .btn-admin-secondary');
    adminButtons.forEach(btn => {
        btn.addEventListener('click', function() {
            const buttonType = this.classList.contains('btn-admin-primary') ? 'Primary' : 'Secondary';
            console.log(`Admin ${buttonType} button clicked`);
            alert(`Admin ${buttonType} button from layout module!`);
        });
    });
    
    
    const sidebarToggle = document.querySelector('.sidebar-toggle');
    const sidebar = document.querySelector('.admin-sidebar');
    
    if (sidebarToggle && sidebar) {
        sidebarToggle.addEventListener('click', function() {
            sidebar.classList.toggle('-translate-x-full');
        });
    }
});